// Live end-to-end check of the E3 gate with the real Claude Code CLI (Linux, root).
//
//   node tests/live/claude-code-gate.live.ts [scenario ...]      (CLAUDE_BIN overrides the claude binary)
//
// Everything is real except the model: the gate service (src/gate/service.ts) with its stores and sockets, the
// managed settings generated by src/gate/adapters/claude-code-settings.ts, the production hook entry
// (src/gate/adapters/claude-code-hook.ts, started by Claude Code through `env -i`), and `claude -p` itself. The model is
// a local faux Messages API (no credentials, no network) that plays a script and records what Claude Code sends it,
// so "did the Skill body reach the model" is observed directly.
//
// Claude Code reads managed settings and managed Skills from /etc/claude-code (managed Skills: /etc/claude-code/.claude/
// skills). The script re-runs itself in a private mount namespace (`unshare --mount`) and bind-mounts a temporary
// folder there, so the machine's own /etc/claude-code is never touched. Needs root and util-linux `unshare`.
// Not part of `npm test`; prints one JSON report on stdout and exits 1 if any expectation failed.
import { execFileSync, spawn } from 'node:child_process';
import { existsSync, realpathSync } from 'node:fs';
import { chmod, mkdir, mkdtemp, readFile, rm, rmdir, writeFile } from 'node:fs/promises';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { addApprover, approveSkill, initRoot, updateRevocations } from '../../src/admin.ts';
import { claudeCodeManagedSettings } from '../../src/gate/adapters/claude-code-settings.ts';
import { createGateService, type GateService } from '../../src/gate/service.ts';
import { generateKeyPair } from '../../src/keys.ts';
import type { Mode } from '../../src/policy.ts';

const SELF = fileURLToPath(import.meta.url);
const REPO = path.resolve(path.dirname(SELF), '..', '..');
const CLAUDE = realpathSync(process.env.CLAUDE_BIN ?? execFileSync('sh', ['-c', 'command -v claude'], { encoding: 'utf8' }).trim());
const NODE = realpathSync(process.execPath);
const HOOK_ENTRY = path.join(REPO, 'src/gate/adapters/claude-code-hook.ts');
const MANAGED_ROOT = '/etc/claude-code';
const MANAGED_SKILLS = path.join(MANAGED_ROOT, '.claude', 'skills');
const MARK = (name: string) => `SECRET-BODY-${name}`;
let createdMountPoint = false;

// ---------- faux Messages API ----------
type Block = Record<string, unknown>;
type Step = (body: any) => Block[] | Promise<Block[]>;
let current: { steps: Step[]; requests: any[] } | null = null;
let toolSeq = 0;
const tool = (name: string, input: Record<string, unknown>): Block => ({ type: 'tool_use', id: `toolu_live_${++toolSeq}`, name, input });

function fauxApi(): Promise<{ base: string; close: () => void }> {
  const server = http.createServer((req, res) => {
    let raw = '';
    req.on('data', (c) => (raw += c));
    req.on('end', async () => {
      const json = (o: unknown) => { res.writeHead(200, { 'content-type': 'application/json' }); res.end(JSON.stringify(o)); };
      if (req.method !== 'POST' || !req.url?.startsWith('/v1/messages')) return json({});
      if (req.url.includes('count_tokens')) return json({ input_tokens: 10 });
      const body = JSON.parse(raw);
      let content: Block[] = [{ type: 'text', text: 'ok' }];
      if (current && Array.isArray(body.tools) && body.tools.length) { // main-loop request, not a side query
        current.requests.push(body);
        const step = current.steps[current.requests.length - 1];
        content = step ? await step(body) : [{ type: 'text', text: 'done' }];
      }
      const stop = content.some((c) => c.type === 'tool_use') ? 'tool_use' : 'end_turn';
      const msg = { id: `msg_${Date.now()}`, type: 'message', role: 'assistant', model: body.model, content, stop_reason: stop, stop_sequence: null, usage: { input_tokens: 1, output_tokens: 1 } };
      if (!body.stream) return json(msg);
      res.writeHead(200, { 'content-type': 'text/event-stream' });
      const ev = (type: string, d: object) => res.write(`event: ${type}\ndata: ${JSON.stringify({ type, ...d })}\n\n`);
      ev('message_start', { message: { ...msg, content: [], stop_reason: null } });
      content.forEach((c, index) => {
        if (c.type === 'text') {
          ev('content_block_start', { index, content_block: { type: 'text', text: '' } });
          ev('content_block_delta', { index, delta: { type: 'text_delta', text: c.text } });
        } else {
          ev('content_block_start', { index, content_block: { ...c, input: {} } });
          ev('content_block_delta', { index, delta: { type: 'input_json_delta', partial_json: JSON.stringify(c.input) } });
        }
        ev('content_block_stop', { index });
      });
      ev('message_delta', { delta: { stop_reason: stop, stop_sequence: null }, usage: { output_tokens: 1 } });
      ev('message_stop', {});
      res.end();
    });
  });
  return new Promise((resolve) => server.listen(0, '127.0.0.1', () => {
    const address = server.address() as { port: number };
    resolve({ base: `http://127.0.0.1:${address.port}`, close: () => server.close() });
  }));
}

function textsOf(body: any): string {
  return [...(body.system ?? []), ...body.messages.flatMap((m: any) => [].concat(m.content))]
    .map((c: any) => (typeof c === 'string' ? c : c?.text ?? (typeof c?.content === 'string' ? c.content : JSON.stringify(c?.content ?? '')))).join('\n');
}

/** Every name in the "available skills" listing the model is shown. */
function listing(body: any): string[] {
  const texts = textsOf(body);
  const i = texts.indexOf('The following skills are available');
  if (i < 0) return [];
  return [...texts.slice(i).split('\n\n')[1]!.matchAll(/^- (\S+): /gmu)].map((m) => m[1]!);
}

/** Names of this test's Skills in that listing. */
const advertised = (body: any): string[] => listing(body).filter((n) => n.includes('skill'));

function toolResults(body: any): Array<{ is_error: boolean; text: string }> {
  const out: Array<{ is_error: boolean; text: string }> = [];
  for (const m of body.messages) for (const c of [].concat(m.content) as any[]) if (c?.type === 'tool_result') {
    const t = typeof c.content === 'string' ? c.content : (c.content ?? []).map((x: any) => x.text ?? '').join('');
    out.push({ is_error: !!c.is_error, text: t.slice(0, 200) });
  }
  return out;
}

// ---------- organisation, gate service, managed settings ----------
interface World {
  root: string;
  base: string;
  service: GateService | null;
  mode: Mode;
  org: { rootKey: string; trustRoot: string; revocations: string; approverKey: string };
  certs: Map<string, { path: string; digest: string }>;
  start: (mode: Mode) => Promise<void>;
  stop: () => Promise<void>;
  install: (name: string) => Promise<string>;
  revoke: (name: string) => Promise<unknown>;
  status: () => Promise<unknown>;
}

async function writeSkill(dir: string, name: string): Promise<string> {
  const skill = path.join(dir, name);
  await mkdir(skill, { recursive: true });
  await writeFile(path.join(skill, 'SKILL.md'), `---\nname: ${name}\ndescription: Live-test Skill ${name}.\n---\n# ${name}\n${MARK(name)}\n`);
  return skill;
}

async function world(base: string): Promise<World> {
  const root = realpathSync(await mkdtemp(path.join(os.tmpdir(), 'mago-live-cc-')));
  await chmod(root, 0o755);
  // The managed folder: a private copy bind-mounted over /etc/claude-code (this process's mount namespace only).
  const managedHost = path.join(root, 'etc-claude-code');
  await mkdir(managedHost, { recursive: true, mode: 0o755 });
  createdMountPoint = !existsSync(MANAGED_ROOT);
  await mkdir(MANAGED_ROOT, { recursive: true });
  execFileSync('mount', ['--bind', managedHost, MANAGED_ROOT]);
  await mkdir(path.join(MANAGED_ROOT, '.claude'), { mode: 0o755 });

  const keys = path.join(root, 'keys');
  await mkdir(keys, { mode: 0o700 });
  const rootPair = await generateKeyPair(path.join(keys, 'root.pem'), path.join(keys, 'root.pub'));
  const approver = await generateKeyPair(path.join(keys, 'approver.pem'), path.join(keys, 'approver.pub'));
  const org = { rootKey: rootPair.privatePath, trustRoot: path.join(root, 'trust-root.json'), revocations: path.join(root, 'revocations.json'), approverKey: approver.privatePath };
  const now = new Date();
  await initRoot({ rootKeyPath: org.rootKey, trustRootOut: org.trustRoot, revocationsOut: org.revocations, now });
  await addApprover({ rootKeyPath: org.rootKey, trustRootPath: org.trustRoot, now, publicKeyPath: approver.publicPath, name: 'Live reviewer', scopes: ['*'], expires: '30d' });

  const sources = path.join(root, 'sources');
  const certs = new Map<string, { path: string; digest: string }>();
  const b64 = async (f: string) => (await readFile(f)).toString('base64');
  let generation = 0;

  const w: World = {
    root, base, service: null, mode: 'enforce', org, certs,
    async start(mode) {
      generation += 1;
      const state = path.join(root, `gate-${generation}`);
      await mkdir(state, { mode: 0o755 });
      w.mode = mode;
      w.service = createGateService({
        stateDir: path.join(state, 'state'), generationsDir: path.join(state, 'gens'), managedDir: MANAGED_SKILLS,
        decisionSocketDir: path.join(state, 'dec'), adminSocketDir: path.join(state, 'adm'),
        rootFingerprint: rootPair.keyId, mode, hostExes: [CLAUDE], rootUid: 0,
      });
      await w.service.start();
      const accepted = await w.service.handleAdmin({ v: 1, cmd: 'accept-trust', trust_root_b64: await b64(org.trustRoot), revocations_b64: await b64(org.revocations) });
      if (!accepted.ok) throw new Error(`accept-trust: ${accepted.error}`);
      // The hook's config and the managed settings, as an administrator would install them.
      const config = path.join(state, 'claude-code-hook.json');
      await writeFile(config, JSON.stringify({ v: 1, socket: w.service.sockets.decision, mode, host_exes: [CLAUDE], client_deadline_ms: 1500, self_deadline_ms: 3000 }), { mode: 0o644 });
      const settings = claudeCodeManagedSettings({ mode, nodePath: NODE, hookEntry: HOOK_ENTRY, configPath: config, hookTimeoutSec: 5, selfDeadlineMs: 3000 });
      await writeFile(path.join(MANAGED_ROOT, 'managed-settings.json'), JSON.stringify(settings, null, 2), { mode: 0o644 });
    },
    async stop() {
      await w.service?.stop();
      w.service = null;
    },
    async install(name) {
      const dir = await writeSkill(sources, name);
      const out = path.join(root, `${name}.cert.json`);
      const issued = await approveSkill({ skillDir: dir, approverKeyPath: org.approverKey, now: new Date(), expires: '7d', reason: 'live test', out });
      certs.set(name, { path: out, digest: issued.digest });
      const r = await w.service!.handleAdmin({ v: 1, cmd: 'install', skill_name: name, source_dir: dir, certificate_b64: await b64(out) });
      if (!r.ok) throw new Error(`install ${name}: ${r.error}`);
      return issued.digest;
    },
    async revoke(name) {
      const digest = certs.get(name)!.digest;
      await updateRevocations({ rootKeyPath: org.rootKey, revocationsPath: org.revocations, now: new Date(), revokeDigest: digest, reason: 'live test revoke' });
      return await w.service!.handleAdmin({ v: 1, cmd: 'accept-trust', trust_root_b64: await b64(org.trustRoot), revocations_b64: await b64(org.revocations) });
    },
    async status() {
      return await w.service?.handleAdmin({ v: 1, cmd: 'status' });
    },
  };
  return w;
}

// ---------- one claude -p run ----------
interface Run {
  prompt?: string;
  steps?: Step[];
  args?: string[];
}

async function runClaude(w: World, name: string, run: Run) {
  const dir = path.join(w.root, 'runs', name);
  const home = path.join(dir, 'home');
  const cfg = path.join(dir, 'cfg');
  const proj = path.join(dir, 'proj');
  for (const d of [home, cfg, proj]) await mkdir(d, { recursive: true });
  // Skills the organisation never approved: one in the project, one in the user's own folder.
  await writeSkill(path.join(proj, '.claude', 'skills'), 'project-skill');
  await writeSkill(path.join(cfg, 'skills'), 'user-skill');
  current = { steps: run.steps ?? [], requests: [] };
  const env = {
    PATH: process.env.PATH ?? '/usr/bin:/bin', HOME: home, CLAUDE_CONFIG_DIR: cfg,
    ANTHROPIC_API_KEY: 'sk-ant-faux', ANTHROPIC_BASE_URL: w.base, DISABLE_AUTOUPDATER: '1',
  };
  const argv = ['-p', run.prompt ?? 'hello', '--debug-file', path.join(dir, 'debug.log'), '--output-format', 'stream-json', '--verbose',
    '--include-hook-events', '--no-session-persistence', ...(run.args ?? [])];
  const child = spawn(CLAUDE, argv, { cwd: proj, env, stdio: ['ignore', 'pipe', 'pipe'] });
  let stdout = '';
  let stderr = '';
  child.stdout.on('data', (d) => (stdout += d));
  child.stderr.on('data', (d) => (stderr += d));
  const timer = setTimeout(() => child.kill('SIGKILL'), 120_000);
  const code = await new Promise<number | null>((r) => child.on('close', r));
  clearTimeout(timer);
  const requests = current.requests;
  current = null;
  const all = JSON.stringify(requests);
  const events = stdout.split('\n').filter(Boolean).map((l) => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
  const result = events.find((e: any) => e.type === 'result');
  const hookEvents = events.filter((e: any) => e.type === 'system' && /hook/u.test(e.subtype ?? ''))
    .map((e: any) => ({ subtype: e.subtype, event: e.hook_event ?? e.hook_event_name, outcome: e.outcome, exit: e.exit_code, out: String(e.stdout ?? e.output ?? '').slice(0, 200), err: String(e.stderr ?? '').slice(0, 200) }));
  return {
    exit: code,
    modelCalls: requests.length,
    advertised: requests[0] ? advertised(requests[0]) : null,
    listing: requests[0] ? listing(requests[0]) : null,
    reached: Object.fromEntries(['approved-skill', 'other-skill', 'planted-skill', 'project-skill', 'user-skill'].map((n) => [n, all.includes(MARK(n))])),
    toolResults: requests.length ? toolResults(requests.at(-1)) : [],
    hookEvents,
    result: result ? String(result.result ?? result.subtype).slice(0, 240) : stderr.slice(0, 400),
  };
}

// ---------- scenarios ----------
type Outcome = Awaited<ReturnType<typeof runClaude>>;
interface Scenario {
  mode: Mode;
  what: string;
  before?: (w: World) => Promise<void>;
  run: (w: World) => Run;
  expect: (o: Outcome, w: World) => Record<string, boolean>;
}

const skillCall = (skill: string): Step => () => [tool('Skill', { skill })];
const errorText = (o: Outcome) => o.toolResults.map((r) => `${r.is_error ? 'ERROR ' : ''}${r.text}`).join(' | ');

const SCENARIOS: Record<string, Scenario> = {
  'listing': {
    mode: 'enforce', what: 'only the gate-installed Skill (a symlink in the managed folder) is listed; project and user Skills are not',
    run: () => ({}),
    expect: (o) => ({
      'approved-skill listed': o.advertised?.includes('approved-skill') === true,
      'project-skill not listed': o.advertised?.includes('project-skill') === false,
      'user-skill not listed': o.advertised?.includes('user-skill') === false,
    }),
  },
  'skill-tool-approved': {
    mode: 'enforce', what: 'the model calls the Skill tool on the installed Skill: allowed, its body reaches the model',
    run: () => ({ steps: [skillCall('approved-skill')] }),
    expect: (o) => ({ 'approved body reached the model': o.reached['approved-skill'] === true }),
  },
  'skill-tool-project': {
    mode: 'enforce', what: 'the model calls the Skill tool on a project Skill: refused, its body never reaches the model',
    run: () => ({ steps: [skillCall('project-skill')] }),
    expect: (o) => ({ 'project body did not reach the model': o.reached['project-skill'] === false, 'the call returned an error': o.toolResults.some((r) => r.is_error) }),
  },
  'slash-approved': {
    mode: 'enforce', what: 'the user types /approved-skill: expanded, its body reaches the model',
    run: () => ({ prompt: '/approved-skill go' }),
    expect: (o) => ({ 'approved body reached the model': o.reached['approved-skill'] === true }),
  },
  'slash-project': {
    mode: 'enforce', what: 'the user types /project-skill: not expanded, the body never reaches the model',
    run: () => ({ prompt: '/project-skill go' }),
    expect: (o) => ({ 'project body did not reach the model': o.reached['project-skill'] === false }),
  },
  'revoke-mid-session': {
    mode: 'enforce', what: 'the approval is revoked after the session started: the next Skill call in that session is denied',
    before: async (w) => { await w.install('other-skill'); },
    run: (w) => ({ steps: [async () => { await w.revoke('other-skill'); return [tool('Skill', { skill: 'other-skill' })]; }] }),
    expect: (o) => ({
      'other-skill was listed at start': o.advertised?.includes('other-skill') === true,
      'its body did not reach the model after the revoke': o.reached['other-skill'] === false,
      'the call returned an error': o.toolResults.some((r) => r.is_error),
    }),
  },
  'revoked-new-session': {
    mode: 'enforce', what: 'after the revoke, a new session no longer lists the auto-uninstalled Skill',
    run: () => ({ steps: [skillCall('other-skill')] }),
    expect: (o) => ({ 'other-skill not listed': o.advertised?.includes('other-skill') === false, 'its body did not reach the model': o.reached['other-skill'] === false }),
  },
  'planted-skill-tool': {
    mode: 'enforce', what: 'a Skill copied straight into the managed folder (not installed by the gate) is loaded by Claude Code, but the hook refuses the Skill tool call',
    before: async () => { await writeSkill(MANAGED_SKILLS, 'planted-skill'); },
    run: () => ({ steps: [skillCall('planted-skill')] }),
    expect: (o) => ({
      'planted-skill is listed (native lock lets it through)': o.advertised?.includes('planted-skill') === true,
      'its body did not reach the model': o.reached['planted-skill'] === false,
      'the hook denied it': o.toolResults.some((r) => r.is_error && /not approved by your organisation/u.test(r.text)),
    }),
  },
  'planted-skill-slash': {
    mode: 'enforce', what: 'the same planted Skill typed as /planted-skill: the hook blocks the expansion',
    run: () => ({ prompt: '/planted-skill go' }),
    expect: (o) => ({ 'its body did not reach the model': o.reached['planted-skill'] === false, 'the prompt was blocked': /blocked by hook/u.test(o.result) }),
  },
  'service-down': {
    mode: 'enforce', what: 'the gate service is stopped: the installed Skill is still listed, but every use is denied (fail closed)',
    before: async (w) => { await rm(path.join(MANAGED_SKILLS, 'planted-skill'), { recursive: true, force: true }); await w.stop(); },
    run: () => ({ steps: [skillCall('approved-skill')] }),
    expect: (o) => ({ 'approved body did not reach the model': o.reached['approved-skill'] === false, 'the call returned an error': o.toolResults.some((r) => r.is_error) }),
  },
  'slash-service-down': {
    mode: 'enforce', what: 'the gate service is stopped: /approved-skill is blocked (fail closed)',
    run: () => ({ prompt: '/approved-skill go' }),
    expect: (o) => ({ 'approved body did not reach the model': o.reached['approved-skill'] === false }),
  },
  'shadow-project': {
    mode: 'shadow', what: 'shadow mode: nothing is blocked or hidden; a project Skill is listed and runs',
    run: () => ({ steps: [skillCall('project-skill')] }),
    expect: (o) => ({ 'project-skill listed': o.advertised?.includes('project-skill') === true, 'project body reached the model': o.reached['project-skill'] === true }),
  },
};

async function main(): Promise<void> {
  const api = await fauxApi();
  const w = await world(api.base);
  const pick = process.argv.slice(2);
  const report: unknown[] = [];
  let failed = 0;
  let started = false;
  try {
    for (const [name, scenario] of Object.entries(SCENARIOS)) {
      if (pick.length && !pick.includes(name)) continue;
      if (!started || w.mode !== scenario.mode) {
        // A fresh service in the scenario's mode; earlier stores are kept on disk but not used.
        await w.stop();
        await w.start(scenario.mode);
        await w.install('approved-skill');
        started = true;
      }
      await scenario.before?.(w);
      const outcome = await runClaude(w, name, scenario.run(w));
      const checks = scenario.expect(outcome, w);
      const pass = Object.values(checks).every(Boolean);
      if (!pass) failed += 1;
      report.push({ scenario: name, mode: scenario.mode, what: scenario.what, pass, checks, ...outcome, toolErrors: errorText(outcome) });
      process.stderr.write(`${pass ? 'PASS' : 'FAIL'} ${name}\n`);
    }
  } finally {
    const status = await w.status().catch(() => null);
    await w.stop();
    api.close();
    execFileSync('umount', [MANAGED_ROOT]);
    if (createdMountPoint) await rmdir(MANAGED_ROOT).catch(() => {}); // the empty mount point this run created
    if (process.env.MAGO_LIVE_KEEP !== '1') await rm(w.root, { recursive: true, force: true });
    console.log(JSON.stringify({
      claude: execFileSync(CLAUDE, ['--version'], { encoding: 'utf8' }).trim(), node: process.version, managedSkills: MANAGED_SKILLS,
      failed, scenarios: report, lastServiceStatus: status, keptAt: process.env.MAGO_LIVE_KEEP === '1' ? w.root : undefined,
    }, null, 2));
  }
  process.exitCode = failed ? 1 : 0;
}

// ---------- run inside a private mount namespace ----------
if (process.env.MAGO_LIVE_NS !== '1') {
  if (process.getuid?.() !== 0) {
    console.log(JSON.stringify({ skipped: 'needs root (managed settings live in /etc/claude-code)' }));
    process.exit(0);
  }
  const child = spawn('unshare', ['--mount', '--propagation', 'private', NODE, SELF, ...process.argv.slice(2)], {
    stdio: 'inherit', env: { ...process.env, MAGO_LIVE_NS: '1' },
  });
  child.on('close', (code) => process.exit(code ?? 1));
} else {
  await main();
}
